<template><section class="scr-card"><div class="scr-form-grid"><label class="scr-field"><span>{{ t('race.formation') }}</span><select v-model="options.mode"><option v-for="formation in formations" :key="formation">{{ formation }}</option></select></label><label class="scr-field"><span>{{ t('race.spacingMode') }}</span><select v-model="options.spacingMode"><option value="automatic">automatic</option><option value="manual">manual</option></select></label><NumericInput v-model="options.longitudinalSpacing" :label="t('race.longitudinal')" :min="2" :max="50" :step="0.5" /><NumericInput v-model="options.lateralSpacing" :label="t('race.lateral')" :min="1" :max="25" :step="0.5" /><NumericInput v-model="options.safetyMargin" :label="t('race.safetyMargin')" :min="0" :max="10" :step="0.25" /><label class="scr-field"><span>headingMode</span><select v-model="options.headingMode"><option value="camera">camera</option><option value="road">road</option><option value="custom">custom</option></select></label><NumericInput v-if="options.mode === 'Custom point'" v-model="options.customPointX" label="customPointX" /><NumericInput v-if="options.mode === 'Custom point'" v-model="options.customPointY" label="customPointY" /><NumericInput v-if="options.mode === 'Custom point'" v-model="options.customPointZ" label="customPointZ" /></div><div class="scr-actions"><button type="button" @click="preview">{{ t('race.preview') }}</button><button type="button" @click="spawn('one')">{{ t('race.placeOne') }}</button><button type="button" @click="spawn('next')">{{ t('race.placeNext') }}</button><button type="button" class="is-hot" @click="spawn('all')">{{ t('race.placeAll') }}</button><button type="button" @click="stores.command.send('cancelLineupSpawn')">{{ t('race.cancelPlacement') }}</button></div></section></template>
<script setup>
import { useStores } from "../../stores"; import NumericInput from "../common/NumericInput.vue"
const stores = useStores(); const options = stores.race.state.placementOptions; const { t } = stores.i18n; const formations = ["Automatic Best Fit", "Split Left and Right", "Single File Behind", "Single File Ahead", "Staggered Grid", "Side-by-side Grid", "Circular / Radial", "Front Left", "Behind Right", "Custom point", "Collision"]
function merged() { return { ...options, mode: stores.race.state.options.formation || options.mode, spacingMode: stores.race.state.options.spacingMode || options.spacingMode, longitudinalSpacing: stores.race.state.options.longitudinalSpacing || options.longitudinalSpacing, lateralSpacing: stores.race.state.options.lateralSpacing || options.lateralSpacing, safetyMargin: stores.race.state.options.safetyMargin || options.safetyMargin } }
const preview = () => stores.command.send("previewLineupSpawn", [merged()]); function spawn(variant) { const value = merged(); value.spawnAll = variant === "all"; value.useNextLineupCompetitor = variant !== "one"; value.count = variant === "all" ? Number(stores.race.state.options.count || 4) : 1; stores.command.send("startLineupSpawn", [value]) }
</script>
